  1	package jobs
  2	
  3	import (
  4		"crypto/rand"
  5		"database/sql"
  6		"encoding/hex"
  7		"encoding/json"
  8		"fmt"
  9		"github.com/lib/pq"
 10		"math"
 11		"queuelet/internal/store"
 12		"time"
 13	)
 14	
 15	type Service struct{ S *store.Store }
 16	
 17	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
 18	
 19	// MaxSeconds bounds every seconds-valued input so that now+seconds never
 20	// leaves time.Duration's range (about 292 years).
 21	const MaxSeconds = math.MaxInt32
 22	
 23	// DefaultMaxSeconds caps each retry wait of a queue without backoff.max_seconds.
 24	const DefaultMaxSeconds = 3600
 25	
 26	// Backoff is the wait before retry attempt+1. It saturates at the queue's cap
 27	// (maxSeconds > 0), or at DefaultMaxSeconds or the base if that is larger.
 28	func Backoff(kind string, base, attempt, maxSeconds int) time.Duration {
 29		limit := float64(max(DefaultMaxSeconds, base))
 30		if maxSeconds > 0 {
 31			limit = float64(maxSeconds)
 32		}
 33		steps := float64(attempt)
 34		if kind != "linear" {
 35			steps = math.Exp2(float64(attempt - 1))
 36		}
 37		return time.Duration(min(float64(base)*steps, limit) * float64(time.Second))
 38	}
 39	
 40	const LeaseOrder = "priority DESC, created_at, id"
 41	
 42	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
 43		tx, e := j.S.DB.Begin()
 44		if e != nil {
 45			return nil, e
 46		}
 47		defer tx.Rollback()
 48		var sec int
 49		var paused bool
 50		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
 51			return nil, e
 52		}
 53		if paused {
 54			return []map[string]any{}, nil
 55		}
 56		var kinds pq.StringArray
 57		if e = tx.QueryRow(`SELECT kinds FROM workers WHERE id=$1`, w).Scan(&kinds); e != nil {
 58			return nil, e
 59		}
 60		rows, e := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state='queued' AND kind=ANY($2) ORDER BY `+LeaseOrder+` LIMIT $3 FOR UPDATE SKIP LOCKED`, q, kinds, max)
 61		if e != nil {
 62			return nil, e
 63		}
 64		ids := []int64{}
 65		for rows.Next() {
 66			var id int64
 67			rows.Scan(&id)
 68			ids = append(ids, id)
 69		}
 70		rows.Close()
 71		out := []map[string]any{}
 72		for _, id := range ids {
 73			token := Token()
 74			var payload []byte
 75			var kind string
 76			var attempt int
 77			e = tx.QueryRow(`UPDATE jobs SET state='leased',leased_at=$5,event_at=$5,leased_by=$2,lease_token=$3,lease_expires_at=$4 WHERE id=$1 RETURNING kind,payload,attempts+1`, id, w, token, now.Add(time.Duration(sec)*time.Second), now).Scan(&kind, &payload, &attempt)
 78			if e != nil {
 79				return nil, e
 80			}
 81			out = append(out, map[string]any{"id": id, "kind": kind, "payload": json.RawMessage(payload), "attempt": attempt, "lease_token": token, "lease_expires_at": now.Add(time.Duration(sec) * time.Second)})
 82		}
 83		return out, tx.Commit()
 84	}
 85	func (j *Service) Notify(id int64, now time.Time) error {
 86		var url, secret, state, errtext string
 87		var result []byte
 88		e := j.S.DB.QueryRow(`SELECT q.webhook_url,q.webhook_secret,j.state,COALESCE(j.result,'null'),j.last_error FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id).Scan(&url, &secret, &state, &result, &errtext)
 89		if e != nil {
 90			return e
 91		}
 92		if url == "" {
 93			return nil
 94		}
 95		body, _ := json.Marshal(map[string]any{"job_id": id, "state": state, "result": json.RawMessage(result), "last_error": errtext})
 96		_, e = j.S.DB.Exec(`INSERT INTO webhook_outbox(job_id,url,secret,body,next_at,event_at,namespace_id,queue) SELECT $1,$2,$3,$4,$5,$5,j.namespace_id,q.name FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id, url, secret, string(body), now)
 97		return e
 98	}
 99	func (j *Service) Heartbeat(id int64, token string, seconds int, now time.Time) error {
100		r, e := j.S.DB.Exec(`UPDATE jobs SET lease_expires_at=$3,event_at=$4 WHERE id=$1 AND lease_token=$2 AND state='leased' AND lease_expires_at > $4`, id, token, now.Add(time.Duration(seconds)*time.Second), now)
101		return Changed(r, e)
102	}
103	func Changed(r sql.Result, e error) error {
104		if e != nil {
105			return e
106		}
107		n, e := r.RowsAffected()
108		if e != nil {
109			return e
110		}
111		if n == 0 {
112			return fmt.Errorf("state conflict")
113		}
114		return nil
115	}
116	package jobs
117	
118	import (
119		"database/sql"
120		"encoding/json"
121		"fmt"
122		"time"
123	)
124	
125	func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
126		b, _ := json.Marshal(result)
127		// The joined row is the pre-update snapshot: it still names the holder.
128		var worker int64
129		e := j.S.DB.QueryRow(`UPDATE jobs j SET state='succeeded',event_at=$3,result=$2,finished_at=$3,attempts=j.attempts+1,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL FROM jobs o WHERE o.id=j.id AND j.id=$1 AND j.state='leased' AND j.lease_token=$4 AND j.lease_expires_at > $3 RETURNING o.leased_by`, id, string(b), now, token).Scan(&worker)
130		if e == sql.ErrNoRows {
131			return fmt.Errorf("state conflict")
132		}
133		if e != nil {
134			return e
135		}
136		_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$3,leased_at,$2,'succeeded','' FROM jobs WHERE id=$1`, id, now, worker)
137		if e != nil {
138			return e
139		}
140		return j.Notify(id, now)
141	}
142	package jobs
143	
144	import "time"
145	
146	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
147		tx, e := j.S.DB.Begin()
148		if e != nil {
149			return e
150		}
151		defer tx.Rollback()
152		var attempts, max, base, cap int
153		var kind string
154		var purged bool
155		var worker int64
156		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,COALESCE(q.backoff_max,0),j.leased_by,j.purge_requested FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 AND j.lease_expires_at > $3 FOR UPDATE OF j`, id, token, now).Scan(&attempts, &max, &kind, &base, &cap, &worker, &purged)
157		if e != nil {
158			return e
159		}
160		state := "retry_wait"
161		if !retry || attempts >= max || purged {
162			state = "dead"
163		}
164		wait := Backoff(kind, base, attempts, cap)
165		if delay != nil {
166			wait = time.Duration(*delay) * time.Second
167		}
168		_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$6,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
169		if e != nil {
170			return e
171		}
172		_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,'failed',$4 FROM jobs WHERE id=$1`, id, worker, now, message)
173		if e != nil {
174			return e
175		}
176		if e = tx.Commit(); e != nil {
177			return e
178		}
179		if state == "dead" {
180			return j.Notify(id, now)
181		}
182		return nil
183	}
184	package jobs
185	
186	import "time"
187	
188	func (j *Service) Cancel(id int64, now time.Time) error {
189		r, e := j.S.DB.Exec(`UPDATE jobs SET state='cancelled',event_at=$2,finished_at=$2,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled')`, id, now)
190		if e = Changed(r, e); e != nil {
191			return e
192		}
193		return j.Notify(id, now)
194	}
195	func (j *Service) Retry(id int64, now time.Time) error {
196		r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$2,attempts=0,run_at=$2,finished_at=NULL,purge_requested=false WHERE id=$1 AND state='dead'`, id, now)
197		return Changed(r, e)
198	}
199	package jobs
200	
201	import (
202		"database/sql"
203		"time"
204	)
205	
206	func (j *Service) Expire(now time.Time) error {
207	
208		tx, e := j.S.DB.Begin()
209		if e != nil {
210			return e
211		}
212		defer tx.Rollback()
213		// The event trigger labels this transaction's releases as expiries.
214		if _, e = tx.Exec(`SET LOCAL queuelet.release='lease_expired'`); e != nil {
215			return e
216		}
217		dead, e := release(tx, now, "expired", "lease expired", `state='leased' AND lease_expires_at <= $1 FOR UPDATE SKIP LOCKED`, now)
218		if e != nil {
219			return e
220		}
221		if e = tx.Commit(); e != nil {
222			return e
223		}
224		for _, id := range dead {
225			if e = j.Notify(id, now); e != nil {
226				return e
227			}
228		}
229		return nil
230	}
231	
232	// ReleaseWorker ends a deregistered worker's leases inside the caller's
233	// transaction. The caller notifies the returned dead jobs after commit.
234	func (j *Service) ReleaseWorker(tx *sql.Tx, worker int64, now time.Time) ([]int64, error) {
235		return release(tx, now, "released", "worker deleted", `state='leased' AND leased_by=$1 FOR UPDATE`, worker)
236	}
237	
238	// release ends the selected leases. Each records an unsuccessful attempt; the
239	// job is queued again, or dead when its attempts are spent or its queue was
240	// purged while it ran.
241	func release(tx *sql.Tx, now time.Time, outcome, reason, where string, arg any) ([]int64, error) {
242		rows, e := tx.Query(`SELECT id,attempts+1,max_attempts,leased_by,purge_requested FROM jobs WHERE `+where, arg)
243		if e != nil {
244			return nil, e
245		}
246		type expired struct {
247			id, worker int64
248			n, max     int
249			purged     bool
250		}
251		batch := []expired{}
252		for rows.Next() {
253			var r expired
254			if e = rows.Scan(&r.id, &r.n, &r.max, &r.worker, &r.purged); e != nil {
255				rows.Close()
256				return nil, e
257			}
258			batch = append(batch, r)
259		}
260		e = rows.Err()
261		rows.Close()
262		if e != nil {
263			return nil, e
264		}
265		dead := []int64{}
266		for _, r := range batch {
267			state := "queued"
268			if r.n >= r.max || r.purged {
269				state = "dead"
270				dead = append(dead, r.id)
271			}
272			_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$4,attempts=$3,last_error=$5,run_at=$4,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL,finished_at=CASE WHEN $2='dead' THEN $4::timestamptz ELSE NULL END WHERE id=$1`, r.id, state, r.n, now, reason)
273			if e != nil {
274				return nil, e
275			}
276			_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,$4,$5 FROM jobs WHERE id=$1`, r.id, r.worker, now, outcome, reason)
277			if e != nil {
278				return nil, e
279			}
280		}
281		return dead, nil
282	}
283	
284	func (j *Service) Promote(now time.Time) error {
285		_, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$1 WHERE state IN ('scheduled','retry_wait') AND run_at <= $1`, now)
286		return e
287	}
288	func (j *Service) Retain(now time.Time) error {
289		_, e := j.S.DB.Exec(`WITH removed AS (DELETE FROM jobs j USING queues q WHERE j.queue_id=q.id AND j.state IN ('succeeded','cancelled') AND extract(epoch FROM $1::timestamptz - j.finished_at) / 3600 > q.retention_hours RETURNING j.*) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$1,'retained',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, now)
290		return e
291	}

