 11	func (s *Server) getJob(w http.ResponseWriter, r *http.Request) {
 12		if !s.ownJob(w, r) {
 13			return
 14		}
 15		v, e := s.S.One(`SELECT * FROM jobs WHERE id=$1`, num(r, "id"))
 16		if e != nil {
 17			fail(w, 404, "job_not_found", e)
 18			return
 19		}
 20		write(w, 200, v)
 21	}
 22	func (s *Server) attempts(w http.ResponseWriter, r *http.Request) {
 23		if !s.ownJob(w, r) {
 24			return
 25		}
 26		v, e := s.S.Rows(`SELECT * FROM attempts WHERE job_id=$1 ORDER BY n`, num(r, "id"))
 27		output(w, map[string]any{"attempts": v}, e)
 28	}
 29	func (s *Server) deleteJob(w http.ResponseWriter, r *http.Request) {
 30		if !s.ownJob(w, r) {
 31			return
 32		}
 33		res, e := s.S.DB.Exec(`WITH removed AS (DELETE FROM jobs WHERE id=$1 AND state IN ('succeeded','dead','cancelled') RETURNING *) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$2,'deleted',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, num(r, "id"), s.Clock.Now())
 34		if e = jobs.Changed(res, e); e != nil {
 35			fail(w, 409, "state_conflict", e)
 36			return
 37		}
 38		write(w, 204, nil)
 39	}
 40	func (s *Server) jobVerb(w http.ResponseWriter, r *http.Request) {
 41		if !s.ownJob(w, r) {
 42			return
 43		}
 44		id := num(r, "id")
 45		now := s.Clock.Now()
 46		var e error
 47		switch r.PathValue("verb") {
 48		case "cancel":
 49			e = s.Jobs.Cancel(id, now)
 50		case "retry":
 51			e = s.Jobs.Retry(id, now)
 52		case "ack", "nack", "heartbeat":
 53			var in struct {
 54				LeaseToken    string `json:"lease_token"`
 55				Result        any    `json:"result"`
 56				Error         string `json:"error"`
 57				Retry         *bool  `json:"retry"`
 58				DelaySeconds  *int   `json:"delay_seconds"`
 59				ExtendSeconds int    `json:"extend_seconds"`
 60			}
 61			if !decode(w, r, &in) {
 62				return
 63			}
 64			switch r.PathValue("verb") {
 65			case "ack":
 66				if containsNUL(in.Result) {
 67					fail(w, 400, "invalid_result", "result cannot contain U+0000")
 68					return
 69				}
 70				e = s.Jobs.Ack(id, in.LeaseToken, in.Result, now)
 71			case "nack":
 72				if strings.ContainsRune(in.Error, 0) {
 73					fail(w, 400, "invalid_error", "error cannot contain U+0000")
 74					return
 75				}
 76				if in.DelaySeconds != nil && (*in.DelaySeconds < 0 || *in.DelaySeconds > jobs.MaxSeconds) {
 77					fail(w, 400, "invalid_delay", "delay_seconds must be 0–2147483647")
 78					return
 79				}
 80				retry := true
 81				if in.Retry != nil {
 82					retry = *in.Retry
 83				}
 84				e = s.Jobs.Nack(id, in.LeaseToken, in.Error, retry, in.DelaySeconds, now)
 85			case "heartbeat":
 86				if in.ExtendSeconds < 1 || in.ExtendSeconds > jobs.MaxSeconds {
 87					fail(w, 400, "invalid_extension", "extend_seconds must be 1–2147483647")
 88					return
 89				}
 90				e = s.Jobs.Heartbeat(id, in.LeaseToken, in.ExtendSeconds, now)
 91			}
 92		default:
 93			fail(w, 404, "not_found", "unknown operation")
 94			return
 95		}
 96		if e != nil {
 97			fail(w, 409, "state_conflict", e)
 98			return
 99		}
100		write(w, 200, map[string]any{"ok": true})
101	}
102	func (s *Server) createWorker(w http.ResponseWriter, r *http.Request) {
103		var in struct {
104			Name  string   `json:"name"`
105			Kinds []string `json:"kinds"`
106		}
107		if !decode(w, r, &in) {
108			return
109		}
110		if in.Name == "" || len(in.Kinds) == 0 {
111			fail(w, 400, "invalid_worker", "name and kinds required")
112			return
113		}
114		token := jobs.Token()
115		var id int64
116		e := s.S.DB.QueryRow(`INSERT INTO workers(namespace_id,name,kinds,token,last_seen_at) VALUES($1,$2,$3,$4,$5) RETURNING id`, ident(r).Namespace, in.Name, pq.Array(in.Kinds), token, s.Clock.Now()).Scan(&id)
117		if e != nil {
118			fail(w, 500, "database_error", e)
119			return
120		}
121		write(w, 201, map[string]any{"worker_id": id, "token": token})
122	}
123	func (s *Server) deleteWorker(w http.ResponseWriter, r *http.Request) {
124		tx, e := s.S.DB.Begin()
125		if e != nil {
126			fail(w, 500, "database_error", e)
127			return
128		}
129		defer tx.Rollback()
130		res, e := tx.Exec(`DELETE FROM workers WHERE id=$1 AND namespace_id=$2`, num(r, "id"), ident(r).Namespace)
131		if e = jobs.Changed(res, e); e != nil {
132			fail(w, 404, "worker_not_found", e)
133			return
134		}
135		now := s.Clock.Now()
136		dead, e := s.Jobs.ReleaseWorker(tx, num(r, "id"), now)
137		if e == nil {
138			e = tx.Commit()
139		}
140		for _, id := range dead {
141			if e == nil {
142				e = s.Jobs.Notify(id, now)
143			}
144		}
145		output(w, map[string]any{"ok": true}, e)
146	}
147	func (s *Server) lease(w http.ResponseWriter, r *http.Request, q map[string]any) {
148		var in struct {
149			WorkerID int64 `json:"worker_id"`
150			MaxJobs  int   `json:"max_jobs"`
151		}
152		in.MaxJobs = 1
153		if !decode(w, r, &in) {
154			return
155		}
156		if in.MaxJobs < 1 || in.MaxJobs > 100 {
157			fail(w, 400, "invalid_batch", "max_jobs must be 1–100")
158			return
159		}
160		var exists bool
161		s.S.DB.QueryRow(`SELECT EXISTS(SELECT 1 FROM workers WHERE id=$1 AND namespace_id=$2)`, in.WorkerID, ident(r).Namespace).Scan(&exists)
162		if !exists {
163			fail(w, 404, "worker_not_found", "unknown worker")
164			return
165		}
166		v, e := s.Jobs.Lease(q["id"].(int64), in.WorkerID, in.MaxJobs, s.Clock.Now())
167		output(w, map[string]any{"jobs": v}, e)
168	}
169	
170	func (s *Server) ownJob(w http.ResponseWriter, r *http.Request) bool {
171		var id int64
172		e := s.S.DB.QueryRow(`SELECT id FROM jobs WHERE id=$1 AND namespace_id=$2`, num(r, "id"), ident(r).Namespace).Scan(&id)
173		if e == sql.ErrNoRows {
174			fail(w, 404, "job_not_found", "job not found")
175			return false
176		}
177		if e != nil {
178			fail(w, 500, "database_error", e)
179			return false
180		}
181		return true
182	}
183	
184	// JSON strings and object keys can contain NUL; PostgreSQL jsonb cannot.
185	func containsNUL(v any) bool {
186		switch x := v.(type) {
187		case string:
188			return strings.ContainsRune(x, 0)
189		case []any:
190			for _, value := range x {
191				if containsNUL(value) {
192					return true
193				}
194			}
195		case map[string]any:
196			for key, value := range x {
197				if strings.ContainsRune(key, 0) || containsNUL(value) {
198					return true
199				}
200			}
201		}
202		return false
203	}

