		}
	}
	_, e = tx.Exec(`UPDATE schedules SET next_run_at=$2,last_run_at=CASE WHEN $3 THEN last_run_at ELSE $4 END WHERE id=$1`, id, next, paused, due)
	if e != nil {
		return e
	}
	return tx.Commit()
}

